import{_ as s}from"./plugin-vue_export-helper-c27b6911.js";import{o as a,c as n,e}from"./app-09e0be14.js";const t={},c=e(`<h1 id="emscripten-把-c-c-编译为-webassembly-javascript" tabindex="-1"><a class="header-anchor" href="#emscripten-把-c-c-编译为-webassembly-javascript" aria-hidden="true">#</a> emscripten（把 C/C++ 编译为 WebAssembly/JavaScript）</h1><blockquote><p>Homebrew 版本 4.0.21 ｜ 主页：见官方文档 ｜ 安装：<code>brew install emscripten</code></p></blockquote><h2 id="一、它是什么" tabindex="-1"><a class="header-anchor" href="#一、它是什么" aria-hidden="true">#</a> 一、它是什么</h2><p>Emscripten 是一个完整的 LLVM-to-WebAssembly 编译工具链，能把 C/C++ 源码直接编译成可以在浏览器、Node.js 或其他 JavaScript 运行时中运行的 WebAssembly（<code>.wasm</code>）二进制文件和配套的 JavaScript 胶水代码。它解决的核心问题是：让海量的 C/C++ 遗产代码和成熟库（如 SDL、OpenGL、zlib、SQLite）无需重写就能跑在 Web 平台上。典型应用场景包括把游戏引擎、音视频处理、图像识别、密码学库等高性能模块编译为 wasm，在浏览器中实现接近原生的性能。</p><p>Emscripten 工具链由三部分组成：<code>emcc</code>（主编译器，类似 gcc/clang）、<code>em++</code>（C++ 版本）、<code>emar</code>（归档工具，对应 <code>ar</code>，用于打静态库）、<code>embuilder</code>（预构建/自构建系统库）、<code>emrun</code>（本地测试服务器）、<code>emsh</code>（SDK 环境 shell）以及 <code>em-config</code>/<code>em-config-abi</code> 等辅助工具。这些命令都由 Homebrew 安装后自动加入 PATH，可直接使用。</p><h2 id="二、安装与升级" tabindex="-1"><a class="header-anchor" href="#二、安装与升级" aria-hidden="true">#</a> 二、安装与升级</h2><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 安装</span>
brew <span class="token function">install</span> emscripten

<span class="token comment"># 升级到最新版本</span>
brew upgrade emscripten

<span class="token comment"># 卸载</span>
brew uninstall emscripten

<span class="token comment"># 验证安装成功（打印版本号）</span>
emcc <span class="token parameter variable">--version</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>验证输出类似：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>emcc <span class="token punctuation">(</span>Emscripten gcc/clang-like replacement + linker emulating GNU ld<span class="token punctuation">)</span> <span class="token number">4.0</span>.21 <span class="token punctuation">(</span>4e14c0e2c47ddb60d62ebc1839cc2a7eef94daf2<span class="token punctuation">)</span>
Copyright <span class="token punctuation">(</span>C<span class="token punctuation">)</span> <span class="token number">2014</span> the Emscripten authors <span class="token punctuation">(</span>see AUTHORS.txt<span class="token punctuation">)</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>同时可以确认 WebAssembly 支持情况：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 确认 clang 与 wasm 后端可用</span>
emcc <span class="token parameter variable">-v</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>常用环境变量（在 shell 中 <code>export</code> 即可）也有助于定位工具链位置：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 查看当前配置的 SDK 根目录</span>
<span class="token builtin class-name">echo</span> <span class="token variable">$EMSDK</span>
<span class="token comment"># 若未设置，也可通过 which 定位 emcc 真实安装路径</span>
<span class="token function">which</span> emcc
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="三、常用命令速查" tabindex="-1"><a class="header-anchor" href="#三、常用命令速查" aria-hidden="true">#</a> 三、常用命令速查</h2><table><thead><tr><th>命令</th><th>参数说明</th><th>示例</th></tr></thead><tbody><tr><td><code>emcc</code></td><td>主编译命令（编译 C 源码）</td><td><code>emcc hello.c -o hello.html</code></td></tr><tr><td><code>em++</code></td><td>编译 C++ 源码（等价于 emcc 的 C++ 版本）</td><td><code>em++ main.cpp -o main.js</code></td></tr><tr><td><code>emar</code></td><td>打静态库（对应 <code>ar</code>）</td><td><code>emar rcs libfoo.a foo.o</code></td></tr><tr><td><code>emrun</code></td><td>运行生成 HTML 的本地测试服务器</td><td><code>emrun --port 8080 index.html</code></td></tr><tr><td><code>embuilder</code></td><td>预构建/自构建系统库</td><td><code>embuilder build zlib</code></td></tr><tr><td><code>-O0 / -O1 / -O2 / -O3 / -Os / -Oz</code></td><td>优化级别，O3 体积与性能较均衡，Os/Oz 极致压缩</td><td><code>emcc -O3 code.c -o code.wasm</code></td></tr><tr><td><code>-g / -g0~-g4</code></td><td>调试级别，g4 保留全部符号与源映射</td><td><code>emcc -O0 -g4 code.c -o code.js</code></td></tr><tr><td><code>-s</code></td><td>设置链接/编译选项，如 <code>-s WASM=1</code></td><td><code>emcc main.c -s WASM=1 -o main.js</code></td></tr><tr><td><code>-o</code></td><td>指定输出文件，扩展名决定产物类型</td><td><code>emcc a.c -o a.html</code> / <code>-o a.js</code> / <code>-o a.wasm</code></td></tr><tr><td><code>--bind</code></td><td>启用 embind（把 C++ 类/函数导出给 JS 调用）</td><td><code>em++ --bind api.cpp -o api.js</code></td></tr><tr><td><code>-I</code> / <code>-L</code> / <code>-l</code></td><td>指定头文件路径、库路径、链接库</td><td><code>emcc main.c -Iinclude -lmylib -o out.js</code></td></tr><tr><td><code>-sEXPORTED_FUNCTIONS</code></td><td>显式导出指定函数供 JS 调用</td><td><code>-sEXPORTED_FUNCTIONS=_add</code></td></tr><tr><td><code>-sMODULARIZE=1</code></td><td>生成模块化代码，便于按需加载</td><td><code>-sMODULARIZE=1 -sEXPORT_NAME=MyModule</code></td></tr><tr><td><code>--preload-file</code> / <code>--embed-file</code></td><td>把文件打入虚拟文件系统</td><td><code>emcc app.c --preload-file assets/ -o app.js</code></td></tr></tbody></table><h2 id="四、实际示例" tabindex="-1"><a class="header-anchor" href="#四、实际示例" aria-hidden="true">#</a> 四、实际示例</h2><h3 id="示例-1-编译-c-为-html-在浏览器中运行" tabindex="-1"><a class="header-anchor" href="#示例-1-编译-c-为-html-在浏览器中运行" aria-hidden="true">#</a> 示例 1：编译 C 为 HTML，在浏览器中运行</h3><p>准备一个 C 文件 <code>hello.c</code>：</p><div class="language-c line-numbers-mode" data-ext="c"><pre class="language-c"><code><span class="token macro property"><span class="token directive-hash">#</span><span class="token directive keyword">include</span> <span class="token string">&lt;stdio.h&gt;</span></span>
<span class="token macro property"><span class="token directive-hash">#</span><span class="token directive keyword">include</span> <span class="token string">&lt;emscripten.h&gt;</span></span>

<span class="token keyword">int</span> <span class="token function">main</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token function">printf</span><span class="token punctuation">(</span><span class="token string">&quot;Hello, WebAssembly!\\n&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token keyword">return</span> <span class="token number">0</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>编译生成 HTML：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>emcc hello.c <span class="token parameter variable">-o</span> hello.html
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>用 emrun 启动本地服务器并打开页面，打开浏览器开发者工具（F12）Console 即可看到 <code>Hello, WebAssembly!</code> 输出：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>emrun <span class="token parameter variable">--port</span> <span class="token number">8080</span> hello.html
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><h3 id="示例-2-编译为独立-wasm-并在-node-js-中调用导出函数" tabindex="-1"><a class="header-anchor" href="#示例-2-编译为独立-wasm-并在-node-js-中调用导出函数" aria-hidden="true">#</a> 示例 2：编译为独立 wasm 并在 Node.js 中调用导出函数</h3><p>准备 <code>math.c</code>，声明一个可供 JS 调用的函数：</p><div class="language-c line-numbers-mode" data-ext="c"><pre class="language-c"><code><span class="token macro property"><span class="token directive-hash">#</span><span class="token directive keyword">include</span> <span class="token string">&lt;emscripten.h&gt;</span></span>

EMSCRIPTEN_KEEPALIVE
<span class="token keyword">int</span> <span class="token function">add</span><span class="token punctuation">(</span><span class="token keyword">int</span> a<span class="token punctuation">,</span> <span class="token keyword">int</span> b<span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">return</span> a <span class="token operator">+</span> b<span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>编译时导出该函数：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>emcc math.c <span class="token parameter variable">-o</span> math.js <span class="token parameter variable">-sEXPORTED_FUNCTIONS</span><span class="token operator">=</span>_add <span class="token parameter variable">-sEXPORTED_RUNTIME_METHODS</span><span class="token operator">=</span>ccall,cwrap
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>在 Node.js 中调用：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">node</span> <span class="token parameter variable">-e</span> <span class="token string">&quot;
const m = require(&#39;./math.js&#39;);
const add = m.cwrap(&#39;add&#39;, &#39;number&#39;, [&#39;number&#39;, &#39;number&#39;]);
console.log(&#39;1 + 2 =&#39;, add(1, 2));
&quot;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>输出：<code>1 + 2 = 3</code></p><h3 id="示例-3-编译-c-并用-embind-导出类给-javascript" tabindex="-1"><a class="header-anchor" href="#示例-3-编译-c-并用-embind-导出类给-javascript" aria-hidden="true">#</a> 示例 3：编译 C++ 并用 embind 导出类给 JavaScript</h3><p>准备 <code>greet.cpp</code>：</p><div class="language-cpp line-numbers-mode" data-ext="cpp"><pre class="language-cpp"><code><span class="token macro property"><span class="token directive-hash">#</span><span class="token directive keyword">include</span> <span class="token string">&lt;emscripten/bind.h&gt;</span></span>
<span class="token macro property"><span class="token directive-hash">#</span><span class="token directive keyword">include</span> <span class="token string">&lt;string&gt;</span></span>

<span class="token keyword">class</span> <span class="token class-name">Greeter</span> <span class="token punctuation">{</span>
<span class="token keyword">public</span><span class="token operator">:</span>
    <span class="token function">Greeter</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">:</span> <span class="token function">name_</span><span class="token punctuation">(</span><span class="token string">&quot;world&quot;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span><span class="token punctuation">}</span>
    <span class="token keyword">void</span> <span class="token function">setName</span><span class="token punctuation">(</span><span class="token keyword">const</span> std<span class="token double-colon punctuation">::</span>string<span class="token operator">&amp;</span> n<span class="token punctuation">)</span> <span class="token punctuation">{</span> name_ <span class="token operator">=</span> n<span class="token punctuation">;</span> <span class="token punctuation">}</span>
    std<span class="token double-colon punctuation">::</span>string <span class="token function">greet</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">const</span> <span class="token punctuation">{</span> <span class="token keyword">return</span> <span class="token string">&quot;Hello, &quot;</span> <span class="token operator">+</span> name_ <span class="token operator">+</span> <span class="token string">&quot;!&quot;</span><span class="token punctuation">;</span> <span class="token punctuation">}</span>
<span class="token keyword">private</span><span class="token operator">:</span>
    std<span class="token double-colon punctuation">::</span>string name_<span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">;</span>

<span class="token function">EMSCRIPTEN_BINDINGS</span><span class="token punctuation">(</span>greeter<span class="token punctuation">)</span> <span class="token punctuation">{</span>
    emscripten<span class="token double-colon punctuation">::</span><span class="token generic-function"><span class="token function">class_</span><span class="token generic class-name"><span class="token operator">&lt;</span>Greeter<span class="token operator">&gt;</span></span></span><span class="token punctuation">(</span><span class="token string">&quot;Greeter&quot;</span><span class="token punctuation">)</span>
        <span class="token punctuation">.</span><span class="token generic-function"><span class="token function">constructor</span><span class="token generic class-name"><span class="token operator">&lt;</span><span class="token operator">&gt;</span></span></span><span class="token punctuation">(</span><span class="token punctuation">)</span>
        <span class="token punctuation">.</span><span class="token function">function</span><span class="token punctuation">(</span><span class="token string">&quot;setName&quot;</span><span class="token punctuation">,</span> <span class="token operator">&amp;</span>Greeter<span class="token double-colon punctuation">::</span>setName<span class="token punctuation">)</span>
        <span class="token punctuation">.</span><span class="token function">function</span><span class="token punctuation">(</span><span class="token string">&quot;greet&quot;</span><span class="token punctuation">,</span> <span class="token operator">&amp;</span>Greeter<span class="token double-colon punctuation">::</span>greet<span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>编译：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>em++ greet.cpp <span class="token parameter variable">-o</span> greet.js <span class="token parameter variable">--bind</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>在 Node.js 中调用：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">node</span> <span class="token parameter variable">-e</span> <span class="token string">&quot;
require(&#39;./greet.js&#39;).then(m =&gt; {
    const g = new m.Greeter();
    g.setName(&#39;Emscripten&#39;);
    console.log(g.greet());
});
&quot;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>输出：<code>Hello, Emscripten!</code></p><h3 id="示例-4-配合主循环调用-c-侧函数-游戏-动画" tabindex="-1"><a class="header-anchor" href="#示例-4-配合主循环调用-c-侧函数-游戏-动画" aria-hidden="true">#</a> 示例 4：配合主循环调用 C 侧函数（游戏/动画）</h3><p>Emscripten 提供了 <code>emscripten_set_main_loop</code> 让 C 代码每帧执行回调，配合 <code>emscripten_sleep</code> 实现帧循环，适合游戏、动画、实时计算：</p><div class="language-c line-numbers-mode" data-ext="c"><pre class="language-c"><code><span class="token macro property"><span class="token directive-hash">#</span><span class="token directive keyword">include</span> <span class="token string">&lt;emscripten.h&gt;</span></span>
<span class="token macro property"><span class="token directive-hash">#</span><span class="token directive keyword">include</span> <span class="token string">&lt;stdio.h&gt;</span></span>

<span class="token keyword">static</span> <span class="token keyword">int</span> frame <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span>

<span class="token keyword">void</span> <span class="token function">tick</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token function">printf</span><span class="token punctuation">(</span><span class="token string">&quot;frame %d\\n&quot;</span><span class="token punctuation">,</span> <span class="token operator">++</span>frame<span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span>frame <span class="token operator">&gt;=</span> <span class="token number">60</span><span class="token punctuation">)</span> <span class="token function">emscripten_cancel_main_loop</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 60 帧后停止</span>
<span class="token punctuation">}</span>

<span class="token keyword">int</span> <span class="token function">main</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token function">emscripten_set_main_loop</span><span class="token punctuation">(</span>tick<span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">,</span> <span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token keyword">return</span> <span class="token number">0</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>编译并打开：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>emcc loop.c <span class="token parameter variable">-o</span> loop.html
emrun <span class="token parameter variable">--port</span> <span class="token number">8080</span> loop.html
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="五、进阶技巧与配置" tabindex="-1"><a class="header-anchor" href="#五、进阶技巧与配置" aria-hidden="true">#</a> 五、进阶技巧与配置</h2><h3 id="_5-1-模块化加载与前端打包" tabindex="-1"><a class="header-anchor" href="#_5-1-模块化加载与前端打包" aria-hidden="true">#</a> 5.1 模块化加载与前端打包</h3><p>默认生成的 JS 会立即自执行，不利于现代前端打包。建议用 <code>-sMODULARIZE=1 -sEXPORT_NAME=MyModule</code> 生成可 Promise 加载的模块，前端配合 <code>Webpack</code>/<code>Vite</code> 使用时更顺手：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>emcc main.c <span class="token parameter variable">-o</span> main.js <span class="token parameter variable">-sMODULARIZE</span><span class="token operator">=</span><span class="token number">1</span> <span class="token parameter variable">-sEXPORT_NAME</span><span class="token operator">=</span>MyModule
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>生成的 <code>main.js</code> 导出一个工厂函数，可在前端这样加载：</p><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token keyword">import</span> MyModule <span class="token keyword">from</span> <span class="token string">&#39;./main.js&#39;</span><span class="token punctuation">;</span>
<span class="token keyword">const</span> m <span class="token operator">=</span> <span class="token keyword">await</span> <span class="token function">MyModule</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>m<span class="token punctuation">.</span><span class="token function">_add</span><span class="token punctuation">(</span><span class="token number">2</span><span class="token punctuation">,</span> <span class="token number">3</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_5-2-定制内存初始化文件与单文件分发" tabindex="-1"><a class="header-anchor" href="#_5-2-定制内存初始化文件与单文件分发" aria-hidden="true">#</a> 5.2 定制内存初始化文件与单文件分发</h3><p>大型 C/C++ 项目会生成 <code>.data</code> 内存初始化文件，前端部署时务必与 <code>.wasm</code>、<code>.js</code> 一同拷贝，并设置正确的 MIME 类型（<code>.data</code> 为 <code>application/octet-stream</code>、<code>.wasm</code> 为 <code>application/wasm</code>）。若想简化部署，可用 <code>-sSINGLE_FILE=1</code> 将 wasm、JS、data 全部 base64 内联进单个 JS 文件，便于 CDN 与离线分发：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 单文件分发（wasm 内联进 JS）</span>
emcc main.c <span class="token parameter variable">-o</span> main.js <span class="token parameter variable">-sSINGLE_FILE</span><span class="token operator">=</span><span class="token number">1</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>注意：<code>SINGLE_FILE</code> 会显著增大 JS 体积（base64 放大约 33%），适合中小模块；大型模块建议保持分离并开启压缩与 HTTP 缓存。</p><h3 id="_5-3-与-cmake-集成" tabindex="-1"><a class="header-anchor" href="#_5-3-与-cmake-集成" aria-hidden="true">#</a> 5.3 与 CMake 集成</h3><p>设置 <code>CMAKE_TOOLCHAIN_FILE</code> 即可用 CMake 原生构建 Emscripten 项目，无需手写 emcc 命令：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>cmake <span class="token parameter variable">-DCMAKE_TOOLCHAIN_FILE</span><span class="token operator">=</span><span class="token variable">$EMSDK</span>/upstream/emscripten/cmake/Modules/Platform/Emscripten.cmake <span class="token parameter variable">-DCMAKE_BUILD_TYPE</span><span class="token operator">=</span>Release <span class="token punctuation">..</span>
<span class="token function">make</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>其中 <code>$EMSDK</code> 是 Emscripten SDK 根目录（Homebrew 安装路径通常为 <code>/opt/homebrew/Cellar/emscripten/&lt;版本&gt;/</code>，可用 <code>which emcc</code> 定位）。</p><p>更规范的做法是在 CMakeLists.txt 中先探测工具链：</p><div class="language-cmake line-numbers-mode" data-ext="cmake"><pre class="language-cmake"><code><span class="token keyword">cmake_minimum_required</span><span class="token punctuation">(</span><span class="token property">VERSION</span> <span class="token number">3.16</span><span class="token punctuation">)</span>
<span class="token keyword">project</span><span class="token punctuation">(</span>mywasm C<span class="token punctuation">)</span>

<span class="token comment"># 启用 wasm 相关的目标属性</span>
<span class="token keyword">set</span><span class="token punctuation">(</span><span class="token variable">CMAKE_C_FLAGS</span> <span class="token string">&quot;<span class="token interpolation"><span class="token punctuation">\${</span><span class="token variable">CMAKE_C_FLAGS</span><span class="token punctuation">}</span></span> -O3&quot;</span><span class="token punctuation">)</span>
<span class="token keyword">set</span><span class="token punctuation">(</span><span class="token variable">CMAKE_EXECUTABLE_SUFFIX</span> <span class="token string">&quot;.js&quot;</span><span class="token punctuation">)</span>

<span class="token keyword">add_executable</span><span class="token punctuation">(</span>main main.c<span class="token punctuation">)</span>
<span class="token keyword">set_target_properties</span><span class="token punctuation">(</span>main <span class="token namespace">PROPERTIES</span>
    <span class="token property">LINK_FLAGS</span> <span class="token string">&quot;-sEXPORTED_FUNCTIONS=_add -sEXPORTED_RUNTIME_METHODS=ccall,cwrap&quot;</span><span class="token punctuation">)</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>构建产物（<code>main.js</code>/<code>main.wasm</code>/<code>main.data</code>）都会输出到构建目录。</p><h3 id="_5-4-常用环境变量" tabindex="-1"><a class="header-anchor" href="#_5-4-常用环境变量" aria-hidden="true">#</a> 5.4 常用环境变量</h3><table><thead><tr><th>环境变量</th><th>作用</th></tr></thead><tbody><tr><td><code>EMCC_DEBUG=1</code></td><td>输出详细编译日志，排查链接/优化问题</td></tr><tr><td><code>EMCC_FORCE_STDLIBS=1</code></td><td>强制链接标准库副本，避免与系统库冲突</td></tr><tr><td><code>EMSDK</code></td><td>SDK 根目录，很多脚本靠它定位工具链</td></tr><tr><td><code>EMCC_CACHE_DIR</code></td><td>指定编译缓存目录（默认 <code>~/.emscripten_cache</code>）</td></tr><tr><td><code>EMCC_LOCAL_PORTS</code></td><td>本地端口/库缓存目录</td></tr><tr><td><code>EMCC_SKIP_SANITY_CHECK=1</code></td><td>跳过环境自检（升级后首次编译建议保持自检）</td></tr></tbody></table><h3 id="_5-5-常用-s-配置项速查" tabindex="-1"><a class="header-anchor" href="#_5-5-常用-s-配置项速查" aria-hidden="true">#</a> 5.5 常用 <code>-s</code> 配置项速查</h3><p><code>-s</code> 选项是 Emscripten 功能的核心，下面列出生产中最常用的一批（注意新旧版本语法都接受，新版本推荐 <code>-sXXX=YYY</code> 无空格写法）：</p><table><thead><tr><th>选项</th><th>作用</th></tr></thead><tbody><tr><td><code>-sWASM=1</code>（默认）</td><td>输出 WebAssembly；<code>=0</code> 则输出 asm.js 兼容代码</td></tr><tr><td><code>-sEXPORTED_RUNTIME_METHODS=ccall,cwrap,FS</code></td><td>导出运行时工具方法</td></tr><tr><td><code>-sEXPORTED_FUNCTIONS=_add,_main</code></td><td>显式导出符号（C 函数加下划线前缀）</td></tr><tr><td><code>-sALLOW_MEMORY_GROWTH=1</code></td><td>允许堆内存按需增长</td></tr><tr><td><code>-sINITIAL_MEMORY=16777216</code></td><td>指定初始堆大小（字节），省去反复扩容开销</td></tr><tr><td><code>-sMAXIMUM_MEMORY=536870912</code></td><td>设置最大堆上限</td></tr><tr><td><code>-sPTHREADS=1</code></td><td>启用 Web Worker 多线程</td></tr><tr><td><code>-sASSERTIONS=1</code>（默认）</td><td>开启运行时断言，调试友好</td></tr><tr><td><code>-sSTACK_SIZE=1048576</code></td><td>设置调用栈大小，递归深的代码需调大</td></tr><tr><td><code>-sMINIFY_HTML=0</code></td><td>不压缩生成的 HTML，便于调试阅读</td></tr><tr><td><code>-sFETCH=1</code></td><td>启用基于 JS Fetch 的网络能力</td></tr><tr><td><code>-sFILESYSTEM=1</code></td><td>启用虚拟文件系统（默认已开启）</td></tr><tr><td><code>-sDISABLE_EXCEPTION_CATCHING=0</code></td><td>开启 C++ 异常捕获（默认关闭以省体积）</td></tr></tbody></table><h3 id="_5-6-编译选项与-webassembly-优化" tabindex="-1"><a class="header-anchor" href="#_5-6-编译选项与-webassembly-优化" aria-hidden="true">#</a> 5.6 编译选项与 WebAssembly 优化</h3><p>除 <code>-O0~-O3</code> 之外，还有一些专门针对 wasm 的调优手段：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 极致体积（-Os 优化体积、-Oz 更激进地牺牲速度）</span>
emcc <span class="token parameter variable">-Os</span> code.c <span class="token parameter variable">-o</span> code.js

<span class="token comment"># 生成可读的 wasm 文本（.wat）便于人工审查</span>
emcc <span class="token parameter variable">-O1</span> code.c <span class="token parameter variable">-sWASM</span><span class="token operator">=</span><span class="token number">1</span> <span class="token parameter variable">-S</span> <span class="token parameter variable">-o</span> code.wat

<span class="token comment"># 开启 Binaryen 优化（默认随 -O 级别自动启用，也可强制指定）</span>
emcc <span class="token parameter variable">-O3</span> --llvm-lto <span class="token number">2</span> code.c <span class="token parameter variable">-o</span> code.js   <span class="token comment"># 开启 LTO 链接期优化，跨文件内联</span>

<span class="token comment"># 压缩 wasm 二进制（部署时用 gzip/brotli）</span>
<span class="token function">gzip</span> <span class="token parameter variable">-k</span> code.wasm
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>体积优化经验：能编译成 C 就别用 C++ 模板爆炸；避免导出过多函数；字符串和全局数据用 <code>-Os</code>；发布前始终压缩 gzip/brotli，wasm 对 gzip 压缩率通常很好。</p><h3 id="_5-7-多线程-pthreads-进阶" tabindex="-1"><a class="header-anchor" href="#_5-7-多线程-pthreads-进阶" aria-hidden="true">#</a> 5.7 多线程（Pthreads）进阶</h3><p>启用多线程需要 <code>-sPTHREADS=1</code>，同时浏览器端必须开启跨域隔离（发送 <code>COOP</code>/<code>COEP</code> 响应头）才能使用 <code>SharedArrayBuffer</code>：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>emcc <span class="token parameter variable">-O3</span> <span class="token parameter variable">-sPTHREADS</span><span class="token operator">=</span><span class="token number">1</span> <span class="token parameter variable">-sALLOW_MEMORY_GROWTH</span><span class="token operator">=</span><span class="token number">1</span> worker.c <span class="token parameter variable">-o</span> worker.js
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>Node.js 侧运行时：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">node</span> --experimental-wasm-threads --experimental-wasm-bulk-memory worker.js
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>跨域隔离响应头（Nginx/开发服务器）示例：</p><div class="language-nginx line-numbers-mode" data-ext="nginx"><pre class="language-nginx"><code><span class="token directive"><span class="token keyword">add_header</span> Cross-Origin-Opener-Policy same-origin</span><span class="token punctuation">;</span>
<span class="token directive"><span class="token keyword">add_header</span> Cross-Origin-Embedder-Policy require-corp</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>注意：多线程 wasm 的初始化是全异步的，<code>Module.onRuntimeInitialized</code> 或 promise 加载时须等待 <code>PThread</code> 完全 ready 再使用。</p><h3 id="_5-8-与其他工具链对比-本系列-n-其他篇衔接" tabindex="-1"><a class="header-anchor" href="#_5-8-与其他工具链对比-本系列-n-其他篇衔接" aria-hidden="true">#</a> 5.8 与其他工具链对比（本系列 n 其他篇衔接）</h3><p>本教程系列还包含 <code>emscripten</code>、<code>cling</code>、<code>nasm</code>、<code>yasm</code> 等编译工具。与它们的分工定位不同：<code>emscripten</code> 面向 Web 平台，把 C/C++ 编为 wasm；<code>cling</code> 是交互式 C++ 解释器，侧重探索与调试；<code>nasm</code>/<code>yasm</code> 则面向 x86/其他架构的汇编编程。若同时学习这些工具，注意它们在命令行风格、输出目标、优化模型上差异很大，不要混用参数。</p><h2 id="六、注意事项与常见问题" tabindex="-1"><a class="header-anchor" href="#六、注意事项与常见问题" aria-hidden="true">#</a> 六、注意事项与常见问题</h2><h3 id="_6-1-新手最常踩的坑" tabindex="-1"><a class="header-anchor" href="#_6-1-新手最常踩的坑" aria-hidden="true">#</a> 6.1 新手最常踩的坑</h3><ol><li><p><strong>文件系统差异</strong>：浏览器中的 wasm 运行在虚拟文件系统（MEMFS）中，<code>fopen</code>/<code>fread</code> 无法直接读取服务器上的真实文件。需要先把文件预加载到虚拟文件系统，常用 <code>--preload-file</code> 或 <code>--embed-file</code> 选项，或通过 JS 侧读取后再传入。</p></li><li><p><strong>函数导出缺失导致调用为 undefined</strong>：JS 只能调用显式导出的函数。忘记加 <code>EMSCRIPTEN_KEEPALIVE</code> 或 <code>-sEXPORTED_FUNCTIONS</code>，直接调用会报 <code>undefined is not a function</code>。导出时注意 C 函数名前加下划线（<code>_add</code>）。</p></li><li><p><strong>没有用 <code>-o xxx.js</code> 而是漏了输出类型</strong>：emcc 默认需要 <code>-o</code> 指定产物类型，忘记写会报 <code>no output</code> 或直接生成 <code>a.out.js</code>。写清楚 <code>-o xxx.html</code> / <code>.js</code> / <code>.wasm</code>。</p></li><li><p><strong>直接 <code>node xxx.js</code> 在无 <code>-sMODULARIZE</code> 时立即自执行</strong>：若只想拿到导出函数而没看到输出，可能是 main 已跑完、进程立即退出。加 <code>-sMODULARIZE=1</code> 并按 Promise 使用即可。</p></li><li><p><strong><code>#include &lt;emscripten.h&gt;</code> 报找不到头文件</strong>：说明未用 emcc/em++ 而误用了系统 gcc/g++。务必通过 emcc 编译，它内置了 Emscripten 头文件路径。</p></li><li><p><strong>浏览器加载 wasm 报 MIME 错误</strong>：<code>.wasm</code> 必须返回 <code>application/wasm</code> 的 Content-Type，本地用 emrun 会自动配好，自己部署静态服务器时需手动配置。</p></li></ol><h3 id="_6-2-常见报错及解决办法" tabindex="-1"><a class="header-anchor" href="#_6-2-常见报错及解决办法" aria-hidden="true">#</a> 6.2 常见报错及解决办法</h3><table><thead><tr><th>报错/现象</th><th>原因</th><th>解决办法</th></tr></thead><tbody><tr><td><code>undefined symbol: _foo</code></td><td>链接时缺少实现</td><td>确认源文件被编译、未声明未定义、导出名与符号一致</td></tr><tr><td><code>unreachable</code> / <code>RuntimeError: memory access out of bounds</code></td><td>越界访问或内存不足</td><td>增大 <code>-sINITIAL_MEMORY</code>、开 <code>-sALLOW_MEMORY_GROWTH=1</code>，检查指针/长度</td></tr><tr><td><code>ReferenceError: Module is not defined</code></td><td>非 MODULARIZE 模式直接 <code>require</code></td><td>用 <code>-sMODULARIZE=1</code> 生成 Promise 模块，或先全局 <code>Module</code></td></tr><tr><td><code>Segmentation fault</code> in Node</td><td>栈溢出或空指针</td><td>调大 <code>-sSTACK_SIZE</code>，用 <code>-O0 -g4</code> 配合 <code>--source-map-base</code> 定位</td></tr><tr><td><code>wasm-opt</code> 报未知 feature</td><td>目标浏览器过旧</td><td>换用 <code>-mtarget-features</code> 或降级优化级别，升级浏览器</td></tr><tr><td><code>error: unknown argument</code></td><td>误传了宿主平台参数</td><td>emcc 是 wasm 交叉编译，去掉 <code>-m64</code>/<code>-march=native</code> 等宿主专用选项</td></tr></tbody></table><h3 id="_6-3-性能与安全注意点" tabindex="-1"><a class="header-anchor" href="#_6-3-性能与安全注意点" aria-hidden="true">#</a> 6.3 性能与安全注意点</h3><ol><li><p><strong>性能与体积权衡</strong>：默认未优化时 wasm 体积大、性能差。发布前务必加 <code>-O3</code>；若追求极致体积可用 <code>-Os</code>。调试时用 <code>-O0 -g4</code> 保留符号便于定位错误。</p></li><li><p><strong>依赖系统库的问题</strong>：有些 C/C++ 库依赖 POSIX 或系统特性，Emscripten 未完全实现（如 fork、部分网络 API、多线程），移植前先确认目标库是否支持 wasm。启用多线程需要 <code>-sPTHREADS=1</code> 并配合 <code>SharedArrayBuffer</code>（需站点开启跨域隔离头）。</p></li><li><p><strong>Node 版本兼容</strong>：生成的 JS 可能在较老 Node 版本上无法运行，建议使用 Node.js 16+；浏览器端注意 wasm 的 MIME 类型需配置为 <code>application/wasm</code> 才可正常加载。</p></li><li><p><strong>升级后缓存失效</strong>：升级 Homebrew 的 emscripten 后，旧的 <code>.wasm</code>/<code>.data</code> 缓存可能不兼容，务必全量重新编译，避免混用不同版本产物导致的崩溃。若 <code>~/.emscripten_cache</code> 报陈旧，可删掉后重新构建：<code>rm -rf ~/.emscripten_cache</code>。</p></li><li><p><strong>安全：避免把敏感数据编译进 wasm</strong>：wasm 与 JS 同样易被逆向，密钥、token 不要硬编码进源码；对输入做边界校验，防止越界读写；对外暴露的导出函数要最小化，减少攻击面。</p></li><li><p><strong>性能：小心字符串与类型转换</strong>：wasm 与 JS 边界来回传字符串/对象开销很大，尽量批量、整块传递数据（如用 typed array 一次性传 Buffer），避免频繁小调用。</p></li><li><p><strong>安全：CSP 与权限</strong>：若站点启用严格内容安全策略，需把 <code>&#39;wasm-unsafe-eval&#39;</code> 加入 <code>script-src</code>，否则 wasm 实例化会被浏览器拦截。</p></li></ol><h2 id="七、实战-与其它工具搭配与自动化" tabindex="-1"><a class="header-anchor" href="#七、实战-与其它工具搭配与自动化" aria-hidden="true">#</a> 七、实战：与其它工具搭配与自动化</h2><h3 id="_7-1-与-webpack-vite-集成" tabindex="-1"><a class="header-anchor" href="#_7-1-与-webpack-vite-集成" aria-hidden="true">#</a> 7.1 与 Webpack / Vite 集成</h3><p>前端构建时把 wasm 当模块使用。以 Vite 为例，安装 vite 插件后直接在 JS 里 import：</p><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token comment">// 编译时生成模块化产物</span>
<span class="token comment">// emcc main.c -o main.js -sMODULARIZE=1 -sEXPORT_NAME=MyModule</span>

<span class="token keyword">import</span> MyModule <span class="token keyword">from</span> <span class="token string">&#39;../wasm/main.js?url&#39;</span><span class="token punctuation">;</span>
<span class="token comment">// 或直接用插件处理 wasm 文件</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>若用 Webpack 5，内置 wasm 支持，可直接：</p><div class="language-javascript line-numbers-mode" data-ext="js"><pre class="language-javascript"><code><span class="token keyword">import</span> main <span class="token keyword">from</span> <span class="token string">&#39;./main.wasm&#39;</span><span class="token punctuation">;</span>
<span class="token function">main</span><span class="token punctuation">(</span><span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">then</span><span class="token punctuation">(</span><span class="token parameter">m</span> <span class="token operator">=&gt;</span> console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>m<span class="token punctuation">.</span><span class="token function">_add</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>推荐统一约定：所有 wasm 产物放入 <code>wasm/</code> 目录，通过构建脚本统一编译，避免每次手敲命令。</p><h3 id="_7-2-用-makefile-自动化编译" tabindex="-1"><a class="header-anchor" href="#_7-2-用-makefile-自动化编译" aria-hidden="true">#</a> 7.2 用 Makefile 自动化编译</h3><p>把常用编译流程固化成 Makefile，增量构建 + 清理：</p><div class="language-makefile line-numbers-mode" data-ext="makefile"><pre class="language-makefile"><code>CC <span class="token operator">:=</span> emcc
CFLAGS <span class="token operator">:=</span> -O3 -sWASM<span class="token operator">=</span>1
EXPORT <span class="token operator">:=</span> -sEXPORTED_FUNCTIONS<span class="token operator">=</span>_add -sEXPORTED_RUNTIME_METHODS<span class="token operator">=</span>ccall,cwrap

SRC <span class="token operator">:=</span> math.c
JS_OUT <span class="token operator">:=</span> dist/math.js
WASM_OUT <span class="token operator">:=</span> dist/math.wasm

<span class="token target symbol">all</span><span class="token punctuation">:</span> <span class="token variable">$</span><span class="token punctuation">(</span>JS_OUT<span class="token punctuation">)</span> <span class="token variable">$</span><span class="token punctuation">(</span>WASM_OUT<span class="token punctuation">)</span>

<span class="token target symbol">dist/%.js dist/%.wasm</span><span class="token punctuation">:</span> %.c
	mkdir -p dist
	<span class="token variable">$</span><span class="token punctuation">(</span>CC<span class="token punctuation">)</span> <span class="token variable">$</span><span class="token punctuation">(</span>CFLAGS<span class="token punctuation">)</span> <span class="token variable">$</span><span class="token punctuation">(</span>EXPORT<span class="token punctuation">)</span> <span class="token variable">$&lt;</span> -o <span class="token variable">$</span><span class="token punctuation">(</span>JS_OUT<span class="token punctuation">)</span>

<span class="token target symbol">clean</span><span class="token punctuation">:</span>
	rm -rf dist

<span class="token builtin-target builtin">.PHONY</span><span class="token punctuation">:</span> all clean
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_7-3-与-cmake-的自动化构建脚本" tabindex="-1"><a class="header-anchor" href="#_7-3-与-cmake-的自动化构建脚本" aria-hidden="true">#</a> 7.3 与 CMake 的自动化构建脚本</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token shebang important">#!/usr/bin/env bash</span>
<span class="token builtin class-name">set</span> <span class="token parameter variable">-euo</span> pipefail

<span class="token assign-left variable">BUILD_DIR</span><span class="token operator">=</span>build-wasm
<span class="token function">mkdir</span> <span class="token parameter variable">-p</span> <span class="token string">&quot;<span class="token variable">$BUILD_DIR</span>&quot;</span>
<span class="token builtin class-name">cd</span> <span class="token string">&quot;<span class="token variable">$BUILD_DIR</span>&quot;</span>

cmake <span class="token parameter variable">-DCMAKE_TOOLCHAIN_FILE</span><span class="token operator">=</span><span class="token string">&quot;<span class="token variable">$EMSDK</span>/upstream/emscripten/cmake/Modules/Platform/Emscripten.cmake&quot;</span> <span class="token punctuation">\\</span>
      <span class="token parameter variable">-DCMAKE_BUILD_TYPE</span><span class="token operator">=</span>Release <span class="token punctuation">\\</span>
      <span class="token punctuation">..</span>
cmake <span class="token parameter variable">--build</span> <span class="token builtin class-name">.</span> -j<span class="token string">&quot;<span class="token variable"><span class="token variable">$(</span><span class="token function">sysctl</span> <span class="token parameter variable">-n</span> hw.ncpu<span class="token variable">)</span></span>&quot;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_7-4-批量编译多个源文件" tabindex="-1"><a class="header-anchor" href="#_7-4-批量编译多个源文件" aria-hidden="true">#</a> 7.4 批量编译多个源文件</h3><p>使用 glob 展开所有源文件一次性编译：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>emcc <span class="token parameter variable">-O3</span> <span class="token parameter variable">-sEXPORTED_RUNTIME_METHODS</span><span class="token operator">=</span>ccall,cwrap <span class="token punctuation">\\</span>
     src/*.c <span class="token parameter variable">-o</span> bundle.js <span class="token parameter variable">-sMODULARIZE</span><span class="token operator">=</span><span class="token number">1</span> <span class="token parameter variable">-sEXPORT_NAME</span><span class="token operator">=</span>Bundle
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>配合 <code>find</code> 收集源文件列表（用于条件排除）：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token assign-left variable">SRCS</span><span class="token operator">=</span><span class="token variable"><span class="token variable">$(</span><span class="token function">find</span> src <span class="token parameter variable">-name</span> <span class="token string">&#39;*.c&#39;</span> <span class="token operator">!</span> <span class="token parameter variable">-name</span> <span class="token string">&#39;*test*&#39;</span><span class="token variable">)</span></span>
emcc <span class="token parameter variable">-O3</span> <span class="token variable">$SRCS</span> <span class="token parameter variable">-o</span> bundle.js <span class="token parameter variable">-sMODULARIZE</span><span class="token operator">=</span><span class="token number">1</span> <span class="token parameter variable">-sEXPORT_NAME</span><span class="token operator">=</span>Bundle
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_7-5-ci-集成-github-actions" tabindex="-1"><a class="header-anchor" href="#_7-5-ci-集成-github-actions" aria-hidden="true">#</a> 7.5 CI 集成（GitHub Actions）</h3><p>在 CI 中安装 emscripten 并构建、跑测试、上传产物：</p><div class="language-yaml line-numbers-mode" data-ext="yml"><pre class="language-yaml"><code><span class="token key atrule">name</span><span class="token punctuation">:</span> wasm<span class="token punctuation">-</span>build
<span class="token key atrule">on</span><span class="token punctuation">:</span> <span class="token punctuation">[</span>push<span class="token punctuation">]</span>
<span class="token key atrule">jobs</span><span class="token punctuation">:</span>
  <span class="token key atrule">build</span><span class="token punctuation">:</span>
    <span class="token key atrule">runs-on</span><span class="token punctuation">:</span> ubuntu<span class="token punctuation">-</span>latest
    <span class="token key atrule">steps</span><span class="token punctuation">:</span>
      <span class="token punctuation">-</span> <span class="token key atrule">uses</span><span class="token punctuation">:</span> actions/checkout@v4
      <span class="token punctuation">-</span> <span class="token key atrule">uses</span><span class="token punctuation">:</span> mymindstorm/setup<span class="token punctuation">-</span>emsdk@v14
      <span class="token punctuation">-</span> <span class="token key atrule">name</span><span class="token punctuation">:</span> Build
        <span class="token key atrule">run</span><span class="token punctuation">:</span> <span class="token punctuation">|</span><span class="token scalar string">
          emcc -O3 -sEXPORTED_FUNCTIONS=_add -sEXPORTED_RUNTIME_METHODS=ccall,cwrap \\
               math.c -o math.js</span>
      <span class="token punctuation">-</span> <span class="token key atrule">name</span><span class="token punctuation">:</span> Test
        <span class="token key atrule">run</span><span class="token punctuation">:</span> node <span class="token punctuation">-</span>e &quot;const m=require(&#39;./math.js&#39;);console.log(m.cwrap(&#39;add&#39;<span class="token punctuation">,</span><span class="token string">&#39;number&#39;</span><span class="token punctuation">,</span><span class="token punctuation">[</span><span class="token string">&#39;number&#39;</span><span class="token punctuation">,</span><span class="token string">&#39;number&#39;</span><span class="token punctuation">]</span>)(2<span class="token punctuation">,</span>3))&quot;
      <span class="token punctuation">-</span> <span class="token key atrule">uses</span><span class="token punctuation">:</span> actions/upload<span class="token punctuation">-</span>artifact@v4
        <span class="token key atrule">with</span><span class="token punctuation">:</span>
          <span class="token key atrule">name</span><span class="token punctuation">:</span> wasm<span class="token punctuation">-</span>dist
          <span class="token key atrule">path</span><span class="token punctuation">:</span> <span class="token punctuation">|</span><span class="token scalar string">
            math.js
            math.wasm</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_7-6-与其他语言工具链搭配" tabindex="-1"><a class="header-anchor" href="#_7-6-与其他语言工具链搭配" aria-hidden="true">#</a> 7.6 与其他语言工具链搭配</h3><ul><li><strong>与 CMake + FetchContent 拉取开源 C/C++ 库</strong>：用 CMake 的 <code>FetchContent</code> 自动下载 zlib、sqlite 等，再统一链接进 wasm，省去手工交叉编译依赖的麻烦。</li><li><strong>与 Node.js 原生模块对比</strong>：Node 侧也可用 N-API 编译原生插件，但 wasm 的跨平台（浏览器+Node+小程序）优势明显，同一份产物可到处跑。</li><li><strong>与 <code>wasm-opt</code> / <code>wasm-objdump</code>（Binaryen）配合</strong>：发布前用 Binaryen 的 <code>wasm-opt -O3</code> 再压一轮，用 <code>wasm-objdump -d</code> 审查指令，帮助定位性能瓶颈。</li><li><strong>与 emscripten 的测试框架（Test Internals）</strong>：可写 <code>*.test.js</code> 调用 wasm 导出做单元测试，在 CI 中统一跑。</li></ul><h3 id="_7-7-生产级实践清单" tabindex="-1"><a class="header-anchor" href="#_7-7-生产级实践清单" aria-hidden="true">#</a> 7.7 生产级实践清单</h3><ul><li>发布流程固定为：<code>-O3</code> + gzip/brotli 压缩 + 正确 MIME。</li><li>产物分离存放（<code>.js</code>/<code>.wasm</code>/<code>.data</code>），开启长期 HTTP 缓存并带内容哈希指纹。</li><li>用 <code>-sMODULARIZE=1 -sEXPORT_NAME</code> 暴露工厂函数，前端按需懒加载。</li><li>对外只导出最小函数集，降低逆向与攻击面。</li><li>用 CMake + Makefile + CI 三层脚本把编译、测试、发布全部自动化。</li><li>记录并固化 emcc 版本号到 <code>package.json</code> 或 README，保证可复现构建。</li></ul><blockquote><p>提示：本教程系列中关于其他编译工具（<code>cling</code>、<code>nasm</code>、<code>yasm</code>）的中文进阶用法，可在本工具分类目录下继续查阅对应文档。</p></blockquote>`,112),o=[c];function p(d,i){return a(),n("div",null,o)}const u=s(t,[["render",p],["__file","emscripten.html.vue"]]);export{u as default};
